CREATE TABLE members(id TEXT PRIMARY KEY,user_id TEXT UNIQUE,name TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE credentials(id TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES members(id),token_hash TEXT NOT NULL UNIQUE,revoked_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE plans(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('period','entries')),quantity INTEGER NOT NULL CHECK(quantity>0),price INTEGER NOT NULL CHECK(price>=0),active INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE memberships(id TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES members(id),plan_id TEXT NOT NULL REFERENCES plans(id),kind TEXT NOT NULL,start_day TEXT NOT NULL,end_day TEXT NOT NULL,remaining INTEGER NOT NULL CHECK(remaining>=0),initial_entries INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','active','revoked')),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE visits(id TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES members(id),credential_id TEXT NOT NULL REFERENCES credentials(id),membership_id TEXT REFERENCES memberships(id),day TEXT NOT NULL,consumed INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL CHECK(status IN ('confirmed','voided')),actor TEXT NOT NULL,created_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,UNIQUE(member_id,day));
CREATE TABLE products(id TEXT PRIMARY KEY,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE variants(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),name TEXT NOT NULL,sku TEXT NOT NULL UNIQUE,price INTEGER NOT NULL CHECK(price>=0),stock INTEGER NOT NULL CHECK(stock>=0),active INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sales(id TEXT PRIMARY KEY,member_id TEXT REFERENCES members(id),status TEXT NOT NULL CHECK(status IN ('pending','confirmed','voided')),created_at TEXT NOT NULL);
CREATE TABLE sale_lines(sale_id TEXT NOT NULL REFERENCES sales(id),variant_id TEXT NOT NULL REFERENCES variants(id),name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price INTEGER NOT NULL CHECK(unit_price>=0),PRIMARY KEY(sale_id,variant_id));
CREATE TABLE payments(id TEXT PRIMARY KEY,source_type TEXT NOT NULL CHECK(source_type IN ('membership','sale')),source_id TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),currency TEXT NOT NULL,method TEXT NOT NULL CHECK(method IN ('cash','transfer','terminal')),status TEXT NOT NULL CHECK(status IN ('pending','confirmed','voided')),reference TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL,confirmed_at TEXT,version INTEGER NOT NULL DEFAULT 1,UNIQUE(source_type,source_id));
CREATE TABLE operation_history(object_type TEXT NOT NULL,object_id TEXT NOT NULL,version INTEGER NOT NULL,snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),actor TEXT NOT NULL,changed_at TEXT NOT NULL,PRIMARY KEY(object_type,object_id,version));
CREATE INDEX visits_day ON visits(day,member_id);
CREATE INDEX payments_status_date ON payments(status,created_at);
CREATE INDEX memberships_member ON memberships(member_id,status);
